import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const theme = {
  colors: { primary: "#2563eb", onPrimary: "#ffffff" },
  spacing: { md: 16 },
  radius: { md: 12 },
};

function App() {
  return (
    <View style={styles.screen}>
      <View nativeID="btn" style={styles.btn}>
        <Text style={styles.btnText}>Сагслах</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: theme.spacing.md, justifyContent: "center" },
  btn: { backgroundColor: theme.colors.primary, padding: theme.spacing.md, borderRadius: theme.radius.md, alignItems: "center" },
  btnText: { color: theme.colors.onPrimary, fontWeight: "bold", fontSize: 16 },
});

registerRootComponent(App);
